import React, { useState, useEffect, useCallback } from 'react';
import { Card, Button, Select, Alert, api, Badge } from '../App';

export default function MarkingPage() {
  const [parties,   setParties]   = useState([]);
  const [saleNos,   setSaleNos]   = useState([]);
  const [grades,    setGrades]    = useState([]);
  const [brokers,   setBrokers]   = useState([]);

  const [partyId,   setPartyId]   = useState('');
  const [saleNo,    setSaleNo]    = useState('');
  const [selGrades, setSelGrades] = useState([]);
  const [priceMin,  setPriceMin]  = useState('');
  const [priceMax,  setPriceMax]  = useState('');
  const [broker,    setBroker]    = useState('');
  const [maxMark,   setMaxMark]   = useState('');
  const [skipBlank, setSkipBlank] = useState(true);
  const [aiWeeks,   setAiWeeks]   = useState('2');

  const [preview,   setPreview]   = useState([]);
  const [loading,   setLoading]   = useState(false);
  const [aiLoading, setAiLoading] = useState(false);
  const [saving,    setSaving]    = useState(false);
  const [alert,     setAlert]     = useState(null);
  const [prices,    setPrices]    = useState({});  // catalogue_id -> final_price
  const [skipped,   setSkipped]   = useState({});  // catalogue_id -> bool

  useEffect(() => {
    Promise.all([
      api.get('/parties'),
      api.get('/import/sale-numbers'),
      api.get('/marking/grades/list'),
      api.get('/marking/brokers/list')
    ]).then(([p, s, g, b]) => {
      setParties(p.data);
      setSaleNos(s.data);
      setGrades(g.data);
      setBrokers(b.data);
    });
  }, []);

  const runPreview = async () => {
    if (!partyId || !saleNo) { setAlert({ msg:'Select party and sale number', type:'error'}); return; }
    setLoading(true);
    setAlert(null);
    try {
      const r = await api.post('/marking/preview', {
        party_id: partyId,
        sale_no: saleNo,
        grades: selGrades,
        price_min: priceMin ? parseFloat(priceMin) : undefined,
        price_max: priceMax ? parseFloat(priceMax) : undefined,
        broker: broker || undefined,
        skip_no_last_price: skipBlank,
        max_mark_space: maxMark ? parseInt(maxMark) : undefined
      });
      setPreview(r.data);
      const initPrices = {};
      r.data.forEach(row => { initPrices[row.catalogue_id] = row.suggested_price || ''; });
      setPrices(initPrices);
      setSkipped({});
      if (r.data.length === 0) setAlert({ msg:'No lots found matching the filters for this party/sale.', type:'warning' });
    } catch (e) {
      setAlert({ msg: e.response?.data?.error || e.message, type:'error' });
    } finally {
      setLoading(false);
    }
  };

  const runAI = async () => {
    if (!partyId || !saleNo) return;
    setAiLoading(true);
    try {
      const r = await api.post('/ai/suggest', { party_id: partyId, sale_no: saleNo, weeks: parseInt(aiWeeks) });
      if (r.data.suggestions?.length > 0) {
        const newPrices = { ...prices };
        r.data.suggestions.forEach(s => {
          const match = preview.find(p => p.garden === s.garden && p.grade === s.grade && p.mark === s.mark);
          if (match) newPrices[match.catalogue_id] = s.suggested_price;
        });
        setPrices(newPrices);
        setAlert({ msg: `✅ AI (${r.data.method}) suggested prices for ${r.data.suggestions.length} lots using ${r.data.history_weeks}-week history`, type:'success' });
      }
    } catch (e) {
      setAlert({ msg: 'AI suggestion failed: ' + e.message, type:'error' });
    } finally {
      setAiLoading(false);
    }
  };

  const save = async () => {
    const markings = preview
      .filter(row => !skipped[row.catalogue_id])
      .map(row => ({
        party_id:      partyId,
        party_name:    row.party_name,
        party_code:    row.party_code,
        garden:        row.garden,
        grade:         row.grade,
        mark:          row.mark,
        bags:          row.bags,
        net_wt:        row.net_wt,
        broker:        row.broker,
        sale_no:       saleNo,
        price_min:     priceMin || undefined,
        price_max:     priceMax || undefined,
        max_mark_space: maxMark || undefined,
        suggested_price: row.suggested_price,
        final_price:   prices[row.catalogue_id] || row.suggested_price,
        status:        'confirmed',
        ai_suggested:  false
      }));

    if (markings.length === 0) { setAlert({ msg:'No markings to save', type:'warning'}); return; }
    setSaving(true);
    try {
      const r = await api.post('/marking/save', { markings, sale_no: saleNo });
      setAlert({ msg:`✅ Saved ${r.data.saved} markings. Proceed to Labels to print.`, type:'success' });
      setPreview([]);
    } catch (e) {
      setAlert({ msg: e.response?.data?.error || e.message, type:'error' });
    } finally {
      setSaving(false);
    }
  };

  const toggleSkip = (id) => setSkipped(s => ({ ...s, [id]: !s[id] }));
  const toggleGrade = (g) => setSelGrades(prev => prev.includes(g) ? prev.filter(x => x!==g) : [...prev, g]);

  const activeCount  = preview.filter(r => !skipped[r.catalogue_id]).length;
  const skippedCount = Object.values(skipped).filter(Boolean).length;

  return (
    <div>
      <h2 style={{ marginBottom:6, color:'#1a3c5e' }}>✅ Create Markings</h2>
      <p style={{ color:'#888', fontSize:13, marginBottom:20 }}>
        Select a party and sale number. Apply filters, optionally use AI suggestions, then save markings.
      </p>

      {alert && <Alert msg={alert.msg} type={alert.type} />}

      {/* Filter panel */}
      <Card>
        <h3 style={{ marginBottom:14, fontSize:15 }}>Filters</h3>
        <div style={{ display:'flex', gap:16, flexWrap:'wrap' }}>
          <div style={{ minWidth:200 }}>
            <Select
              label="Party *"
              value={partyId}
              onChange={setPartyId}
              placeholder="Select party…"
              options={parties.map(p => ({ value: p.id, label: `${p.party_name} (${p.party_code})` }))}
            />
          </div>
          <div style={{ minWidth:160 }}>
            <Select
              label="Sale Number *"
              value={saleNo}
              onChange={setSaleNo}
              placeholder="Select sale…"
              options={saleNos.map(s => ({ value: s.sale_no, label: `${s.sale_no}${s.week_date ? ' ('+new Date(s.week_date).toLocaleDateString('en-IN')+')' : ''}` }))}
            />
          </div>
          <div style={{ minWidth:140 }}>
            <label style={{ display:'block', fontSize:12, fontWeight:600, color:'#444', marginBottom:4 }}>Price Bracket</label>
            <div style={{ display:'flex', gap:6 }}>
              <input value={priceMin} onChange={e => setPriceMin(e.target.value)} placeholder="Min" type="number"
                style={{ width:70, padding:'7px 8px', border:'1.5px solid #cbd5e0', borderRadius:6, fontSize:13 }} />
              <input value={priceMax} onChange={e => setPriceMax(e.target.value)} placeholder="Max" type="number"
                style={{ width:70, padding:'7px 8px', border:'1.5px solid #cbd5e0', borderRadius:6, fontSize:13 }} />
            </div>
          </div>
          <div style={{ minWidth:140 }}>
            <Select label="Broker" value={broker} onChange={setBroker} placeholder="All brokers"
              options={brokers.map(b => ({ value:b, label:b }))} />
          </div>
          <div style={{ minWidth:120 }}>
            <label style={{ display:'block', fontSize:12, fontWeight:600, color:'#444', marginBottom:4 }}>Max Mark Space (bags)</label>
            <input value={maxMark} onChange={e => setMaxMark(e.target.value)} placeholder="e.g. 50" type="number"
              style={{ width:'100%', padding:'7px 8px', border:'1.5px solid #cbd5e0', borderRadius:6, fontSize:13 }} />
          </div>
        </div>

        {/* Grade filter */}
        {grades.length > 0 && (
          <div style={{ marginTop:12 }}>
            <div style={{ fontSize:12, fontWeight:600, color:'#444', marginBottom:6 }}>Grades (click to toggle):</div>
            <div style={{ display:'flex', gap:6, flexWrap:'wrap' }}>
              {grades.map(g => (
                <span key={g} onClick={() => toggleGrade(g)}
                  style={{
                    padding:'3px 10px', borderRadius:20, fontSize:12, fontWeight:600, cursor:'pointer',
                    background: selGrades.includes(g) ? '#1a3c5e' : '#f0f4f8',
                    color: selGrades.includes(g) ? '#fff' : '#555',
                    border:`1.5px solid ${selGrades.includes(g) ? '#1a3c5e' : '#e2e8f0'}`
                  }}>
                  {g}
                </span>
              ))}
              {selGrades.length > 0 && (
                <span onClick={() => setSelGrades([])} style={{ padding:'3px 10px', borderRadius:20, fontSize:12, cursor:'pointer', color:'#c0392b', border:'1.5px solid #c0392b' }}>
                  ✕ Clear grades
                </span>
              )}
            </div>
          </div>
        )}

        <div style={{ marginTop:12, display:'flex', alignItems:'center', gap:16, flexWrap:'wrap' }}>
          <label style={{ display:'flex', alignItems:'center', gap:8, fontSize:13, cursor:'pointer' }}>
            <input type="checkbox" checked={skipBlank} onChange={e => setSkipBlank(e.target.checked)} />
            Skip lots where last sale price is blank
          </label>

          {/* AI options */}
          <div style={{ display:'flex', alignItems:'center', gap:8 }}>
            <span style={{ fontSize:12, color:'#888' }}>AI history:</span>
            <select value={aiWeeks} onChange={e => setAiWeeks(e.target.value)}
              style={{ padding:'4px 8px', border:'1.5px solid #e2e8f0', borderRadius:4, fontSize:12 }}>
              <option value="2">Last 2 weeks</option>
              <option value="4">Last 4 weeks</option>
            </select>
          </div>
        </div>

        <div style={{ marginTop:14, display:'flex', gap:10 }}>
          <Button onClick={runPreview} disabled={loading || !partyId || !saleNo}>
            {loading ? 'Loading…' : '🔍 Preview Lots'}
          </Button>
          {preview.length > 0 && (
            <Button onClick={runAI} disabled={aiLoading} variant="warning">
              {aiLoading ? '🤖 Thinking…' : `🤖 AI Suggest (${aiWeeks}wk)`}
            </Button>
          )}
        </div>
      </Card>

      {/* Preview table */}
      {preview.length > 0 && (
        <Card>
          <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:14 }}>
            <div>
              <h3 style={{ fontSize:15 }}>Preview — {preview.length} lots found</h3>
              <div style={{ fontSize:12, color:'#888', marginTop:2 }}>
                Active: <b style={{ color:'#1a7a4a' }}>{activeCount}</b> · Skipped: <b style={{ color:'#c0392b' }}>{skippedCount}</b>
              </div>
            </div>
            <div style={{ display:'flex', gap:10 }}>
              <Button size="sm" variant="outline" onClick={() => setSkipped(Object.fromEntries(preview.map(r => [r.catalogue_id, false])))}>
                Un-skip All
              </Button>
              <Button onClick={save} disabled={saving || activeCount === 0} variant="success">
                {saving ? 'Saving…' : `💾 Save ${activeCount} Markings`}
              </Button>
            </div>
          </div>

          <div style={{ overflowX:'auto' }}>
            <table style={{ width:'100%', borderCollapse:'collapse', fontSize:12 }}>
              <thead>
                <tr style={{ background:'#f0f4f8' }}>
                  {['Skip','Garden','Grade','Mark','Bags','Net Wt','Last Price','Min','Max','Suggested Price','Broker'].map(h => (
                    <th key={h} style={{ padding:'7px 8px', textAlign:'left', fontWeight:600, color:'#444', borderBottom:'2px solid #e2e8f0', whiteSpace:'nowrap' }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {preview.map((row, i) => {
                  const skip = !!skipped[row.catalogue_id];
                  return (
                    <tr key={row.catalogue_id}
                      style={{ borderBottom:'1px solid #f0f4f8', background: skip ? '#fff5f5' : (i%2===0?'#fff':'#fafbfc'), opacity: skip?0.5:1 }}>
                      <td style={{ padding:'6px 8px' }}>
                        <input type="checkbox" checked={skip} onChange={() => toggleSkip(row.catalogue_id)} />
                      </td>
                      <td style={{ padding:'6px 8px', fontWeight:600 }}>{row.garden}</td>
                      <td style={{ padding:'6px 8px' }}>
                        <Badge color="blue">{row.grade}</Badge>
                      </td>
                      <td style={{ padding:'6px 8px' }}>{row.mark}</td>
                      <td style={{ padding:'6px 8px' }}>{row.bags}</td>
                      <td style={{ padding:'6px 8px' }}>{row.net_wt}</td>
                      <td style={{ padding:'6px 8px', color:'#888' }}>
                        {row.last_sale_price ? `₹${row.last_sale_price}` : <span style={{ color:'#f59e0b' }}>blank</span>}
                      </td>
                      <td style={{ padding:'6px 8px', color:'#1a7a4a' }}>{row.min_last_price ? `₹${row.min_last_price}` : '—'}</td>
                      <td style={{ padding:'6px 8px', color:'#c0392b' }}>{row.max_last_price ? `₹${row.max_last_price}` : '—'}</td>
                      <td style={{ padding:'6px 8px' }}>
                        <div style={{ display:'flex', alignItems:'center', gap:4 }}>
                          <span style={{ color:'#888', fontSize:11 }}>₹</span>
                          <input
                            type="number"
                            value={prices[row.catalogue_id] || ''}
                            onChange={e => setPrices(p => ({ ...p, [row.catalogue_id]: e.target.value }))}
                            style={{ width:70, padding:'3px 6px', border:'1.5px solid #cbd5e0', borderRadius:4, fontSize:12 }}
                          />
                        </div>
                      </td>
                      <td style={{ padding:'6px 8px', color:'#888' }}>{row.broker}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </Card>
      )}
    </div>
  );
}
